INSERT INTO slots VALUES(2,'5-4-1','LCM','CM',40,44,26,'동일',' | [2026-08-19] LDM(DM,x=50,y=45) → LCM(CM,x=40,y=44). FC26 5-4-1의 중앙 2미들은 CM이고 DM 슬롯이 없다. x=40은 07-25 레버쿠젠 이식 초안(team_tactic_setups id=8 · v1 프리셋 첼시 26/27 알론소)의 LCM 앵커다.');
INSERT INTO slots VALUES(2,'5-4-1','RCM','CM',60,44,27,'동일',' | [2026-08-19] RDM(DM,x=61,y=52) → RCM(CM,x=60,y=44). 근거 동일. y 비대칭(45/52)은 실측 파생이었으나 슬롯은 인게임 앵커이므로 대칭 44로 통일하고, 실측 비대칭은 prescriptions에 남는다.');
